triple:
: main
  (forall ρ; ρ n:Int^many -- ρ r:Int^many)
  dup dup prim + prim +;

sum3:
: main
  (forall ρ; ρ a:Int^many b:Int^many c:Int^many -- ρ r:Int^many)
  prim + prim +;

times10:
: main
  (forall ρ; ρ n:Int^many -- ρ r:Int^many)
  dup prim + dup dup prim + dup prim + prim +;

affine:
: main
  (forall ρ; ρ x:Int^many -- ρ r:Int^many)
  dup prim + dup prim + 7 prim +;

pair-sum:
: main
  (forall ρ; ρ a:Int^many b:Int^many -- ρ b2:Int^many s:Int^many)
  locals { a b } { b a b prim + };

select:
: main
  (forall ρ; ρ a:Int^many b:Int^many flag:Bool^many -- ρ r:Int^many)
  [ drop ] [ swap drop ] if;

not:
: main
  (forall ρ; ρ p:Bool^many -- ρ r:Bool^many)
  [ false ] [ true ] if;

and:
: main
  (forall ρ; ρ p:Bool^many q:Bool^many -- ρ r:Bool^many)
  [ ] [ drop false ] if;

xor:
: main
  (forall ρ; ρ p:Bool^many q:Bool^many -- ρ r:Bool^many)
  [ [ false ] [ true ] if ] [ ] if;

majority:
: main
  (forall ρ; ρ p:Bool^many q:Bool^many r:Bool^many -- ρ m:Bool^many)
  \ majority is (p or r) when q holds, else (p and r)
  swap [ or2 ] [ and2 ] if;

: and2
  (forall ρ; ρ p:Bool^many q:Bool^many -- ρ r:Bool^many)
  [ ] [ drop false ] if;

: or2
  (forall ρ; ρ p:Bool^many q:Bool^many -- ρ r:Bool^many)
  [ drop true ] [ ] if;

count-true:
: main
  (forall ρ; ρ p:Bool^many q:Bool^many r:Bool^many -- ρ n:Int^many)
  b2i swap b2i prim + swap b2i prim +;

: b2i
  (forall ρ; ρ p:Bool^many -- ρ n:Int^many)
  [ 1 ] [ 0 ] if;

max:
: main
  (forall ρ; ρ a:Int^many b:Int^many -- ρ r:Int^many)
  max2;

: max2
  (forall ρ; ρ a:Int^many b:Int^many -- ρ m:Int^many)
  over over prim < [ swap drop ] [ drop ] if;

: over
  (forall ρ; ρ a:Int^many b:Int^many -- ρ a:Int^many b:Int^many c:Int^many)
  [ dup ] dip swap;

min3:
: main
  (forall ρ; ρ a:Int^many b:Int^many c:Int^many -- ρ r:Int^many)
  min2 min2;

: min2
  (forall ρ; ρ a:Int^many b:Int^many -- ρ m:Int^many)
  over over prim < [ drop ] [ swap drop ] if;

: over
  (forall ρ; ρ a:Int^many b:Int^many -- ρ a:Int^many b:Int^many c:Int^many)
  [ dup ] dip swap;

clamp:
: main
  (forall ρ; ρ x:Int^many lo:Int^many hi:Int^many -- ρ r:Int^many)
  [ max2 ] dip min2;

: max2
  (forall ρ; ρ a:Int^many b:Int^many -- ρ m:Int^many)
  over over prim < [ swap drop ] [ drop ] if;

: min2
  (forall ρ; ρ a:Int^many b:Int^many -- ρ m:Int^many)
  over over prim < [ drop ] [ swap drop ] if;

: over
  (forall ρ; ρ a:Int^many b:Int^many -- ρ a:Int^many b:Int^many c:Int^many)
  [ dup ] dip swap;

is-even:
: main
  (forall ρ; ρ n:Int^many -- ρ r:Bool^many)
  even?;

: even?
  (forall ρ; ρ n:Int^many -- ρ r:Bool^many)
  dup 2 prim < [ 0 prim = ] [ 2 prim - even? ] if;

sum-to:
: main
  (forall ρ; ρ n:Int^many -- ρ r:Int^many)
  0 swap sum-acc;

: sum-acc
  (forall ρ; ρ acc:Int^many n:Int^many -- ρ r:Int^many)
  dup 0 prim = [ drop ] [ dup [ prim + ] dip 1 prim - sum-acc ] if;

factorial:
: main
  (forall ρ; ρ n:Int^many -- ρ r:Int^many)
  1 swap fact-acc;

: fact-acc
  (forall ρ; ρ acc:Int^many n:Int^many -- ρ r:Int^many)
  dup 0 prim = [ drop ] [ dup [ prim * ] dip 1 prim - fact-acc ] if;

fib:
: main
  (forall ρ; ρ n:Int^many -- ρ r:Int^many)
  0 swap 1 swap fib-loop;

: fib-loop
  (forall ρ; ρ a:Int^many b:Int^many n:Int^many -- ρ r:Int^many)
  dup 0 prim = [ drop drop ] [ 1 prim - [ dup [ prim + ] dip swap ] dip fib-loop ] if;

power:
: main
  (forall ρ; ρ base:Int^many exp:Int^many -- ρ r:Int^many)
  [ 1 swap ] dip pow-loop;

: pow-loop
  (forall ρ; ρ acc:Int^many b:Int^many e:Int^many -- ρ r:Int^many)
  dup 0 prim = [ drop drop ] [ 1 prim - [ dup [ prim * ] dip ] dip pow-loop ] if;
